// no — Norsk (norueguês), em BOKMÅL.
//
// A chave é o TEXTO EM PORTUGUÊS, exatamente como aparece no código. O que faltar aqui aparece em
// português, e não como tela vazia.
//
// QUAL NORUEGUÊS: a Noruega tem duas formas escritas oficiais, bokmål e nynorsk. Este arquivo é bokmål,
// que é o que uns 85–90% escrevem e o que quase toda interface norueguesa usa. O navegador de quem
// escreve nynorsk manda "nn", e o de quem escreve bokmål manda "nb" — nunca "no". Os dois caem aqui pelo
// apelido em web/src/i18n/index.ts, porque nynorsk lê bokmål sem esforço.
//
// NÃO É O DINAMARQUÊS. O bokmål nasceu do dinamarquês escrito e as duas se leem, mas a ortografia é
// outra (meg/deg, ikke/ennå, "lagre" e não "gem", "passord" e não "adgangskode").
//
// TOM: **du**. O *De* de cortesia saiu do norueguês corrente nos anos 1970 e hoje soa antiquado até em
// atendimento.
//
// GÊNERO: o "você" não tem. A terceira pessoa tem (han / hun), e o *hen* neutro entrou no dicionário em
// 2022 mas ainda divide opiniões — então, como no dinamarquês, as frases foram refeitas para não precisar
// de pronome nenhum.
//
// NÚMEROS: `Intl.NumberFormat('no')` devolve `1 234 567` — latinos, com espaço.
//
// O DETECTOR DO TESTE DE IDIOMAS: latino — vai o das chaves.
//
// ASPAS: «assim», as do norueguês. Não são apóstrofos, e não colidem com o `'` da chave.
//
// CHAMADA E CONVERSA SÃO PALAVRAS DIFERENTES: *samtale* serve para as duas no norueguês corrente, e o
// Syden as separa. Chamada = anrop; conversa = samtale.
//
// VOCABULÁRIO, decidido uma vez: comunidade = fellesskap, canal = kanal, sala de voz = talerom, mensagem
// = melding, senha = passord, lixeira = papirkurv, tópico = tråd, conta = konto, administrador =
// administrator, dono = eier, cargo = rolle, convite = invitasjon, perfil = profil, transmissão =
// sending, tela = skjerm, membro = medlem, pacote = pakke, enquete = avstemning, denúncia = rapport, vila
// = landsby, guarda-roupa = garderobe, cutucada = dytt, recado (da tela de boas-vindas e do aviso) =
// oppslag.
//
// SOM E VOZ SÃO DUAS PALAVRAS: stemme é a voz, lyd é o som de soundboard e de aviso.
//
// SELO E INSÍGNIA SEPARADOS: selo = segl (o da comunidade), insígnia = merke (a da pessoa).

