  '{tipo} «{item}» ({onde}) saiu do Syden porque {quem} disse ter os direitos. Se você tinha autorização para publicar, responda aqui contando: a sua resposta vai ser levada em conta. Enquanto isso não ficar claro, fica fora. Os termos explicam como funciona, na seção 4: https://syden.chat/termos.html#direito-autoral': '{tipo} «{item}» ({onde}) er fjernet fra Syden fordi {quem} sier å ha rettighetene. Hvis du hadde lov til å publisere det, svar her og forklar: svaret ditt blir tatt med i vurderingen. Inntil det er avklart, forblir det borte. Vilkårene forklarer hvordan det fungerer, i avsnitt 4: https://syden.chat/termos.html#direito-autoral',
