  'Seu chute': 'Ditt gjett',
  'Chutes: {n}': 'Gjett: {n}',
  'Monstros de fantasia': 'Fantasymonstre',
  'Sai um monstro secreto, e cada um chuta outros da lista. Cada chute mostra o que bate com o secreto: tipo, tamanho, nível, alinhamento e como ele se desloca. Quem acertar com menos chutes ganha mais pontos.': 'Et hemmelig monster trekkes, og alle gjetter andre fra listen. Hvert gjett viser hva som stemmer med det hemmelige: type, størrelse, nivå, moral og hvordan det beveger seg. Færre gjett gir flere poeng.',
  'Sai uma figura secreta da mitologia, e cada um chuta outras. Cada chute mostra o que bate com a secreta: a mitologia, o tipo, a forma e o que ela governa. Quem acertar com menos chutes ganha mais pontos.': 'En hemmelig skikkelse fra mytologien trekkes, og alle gjetter andre. Hvert gjett viser hva som stemmer med den hemmelige: mytologien, typen, formen og hva den hersker over. Færre gjett gir flere poeng.',
  'Países': 'Land',
  'Sai um país secreto, e cada um chuta outros. Cada chute mostra a distância e a direção até o secreto, a região, a sub-região e a população. Quem acertar com menos chutes ganha mais pontos.': 'Et hemmelig land trekkes, og alle gjetter andre. Hvert gjett viser avstanden og retningen til det hemmelige landet, regionen, underregionen og befolkningen. Færre gjett gir flere poeng.',
  'Apagar conversa': 'Slett samtalen',
  'A conversa sai da sua lista e as mensagens somem só para você. As outras pessoas continuam vendo tudo, e uma mensagem nova traz a conversa de volta.': 'Samtalen forsvinner fra listen din, og meldingene forsvinner bare for deg. De andre ser fortsatt alt, og en ny melding bringer samtalen tilbake.',
