  'Copa da turma': 'Gjengens cup',
  'Copas da Cenoura que a turma correu até o fim, na Corrida dos coelhos.': 'Gulrotcuper gjengen kjørte til mål, i Kaninløpet.',
  'Bosque': 'Skogen',
