  'Festa dos coelhos': 'Kaninfesten',
  'Cinco rodadas de jogos rápidos, cada um na própria tela: reflexo, pontaria, memória e olho. Quem for melhor em cada rodada ganha mais pontos.': 'Fem runder med raske spill, hver på sin egen skjerm: reflekser, sikting, hukommelse og blikk. Den som er best i hver runde, får flest poeng.',
  'Saque rápido': 'Rask trekning',
  'Espere o sinal e aperte o mais rápido que puder. Antes do sinal, está fora.': 'Vent på signalet og trykk så fort du kan. Før signalet er du ute.',
  'Medidor de força': 'Kraftmåler',
  'Pare a barra o mais perto possível de 100%.': 'Stopp linjen så nær 100 % som mulig.',
  'Parar o relógio': 'Stopp klokka',
  'Pare o relógio em 10 segundos exatos. Os números somem depois de 3.': 'Stopp klokka på nøyaktig 10 sekunder. Tallene forsvinner etter 3.',
  'Jogo dos copos': 'Koppspillet',
  'Veja onde fica a cenoura e siga o copo. Acertar mais rápido vale mais.': 'Se hvor gulroten er, og følg koppen. Riktig fortere er verdt mer.',
  'Siga o coelho': 'Følg kaninen',
  'Repita as setas na ordem. A cada acerto, vem mais uma.': 'Gjenta pilene i rekkefølge. For hvert riktig svar kommer én til.',
