  'A tábua racha quando alguém para em cima. Continue andando e empurre os outros para a água!': 'Planken sprekker når noen blir stående på den. Fortsett å bevege deg, og dytt de andre ut i vannet!',
  'A torre do celeiro': 'Låvetårnet',
