  'A turma caiu.': 'Gjengen falt.',
  'A turma inteira contra a toupeira-rei, que sai das tocas em três fases. Fuja das marcas no chão, pegue os torrões azulados e atire de volta. Ganha a turma, ou ninguém.': 'Hele gjengen mot moldvarpkongen, som kommer opp av hulene i tre faser. Unngå merkene på bakken, plukk opp de blålige jordklumpene og kast dem tilbake. Gjengen vinner, eller ingen.',
  'Abóboras ladeira abaixo': 'Gresskar nedover bakken',
  'Acerte os corvos que passarem. No coelhinho, não!': 'Treff kråkene som flyr forbi. Ikke den lille kaninen!',
  'Acertos: {n}': 'Treff: {n}',
  'Afofa a terra': 'Løsner jorda',
  'Água e sol': 'Vann og sol',
  'Alterne ← e → no ritmo. Com pressa demais, o fôlego acaba.': 'Veksle mellom ← og → i takt. For mye hastverk, og pusten tar slutt.',
  'Ao calendário': 'Til kalenderen',
  'Ao guarda-roupa': 'Til garderoben',
  'Aperte a seta que aparecer para puxar a corda. Errar trava!': 'Trykk på pila som dukker opp for å dra i tauet. Feil trykk låser deg!',
  'Aperte para a roda frear. Ela sempre desliza um pouco antes de parar.': 'Trykk for å bremse hjulet. Det glir alltid litt før det stopper.',
  'Aperte sem parar para nadar. Quando vier um tronco, mergulhe!': 'Trykk uten stans for å svømme. Når en tømmerstokk kommer, dykk!',
  'Armadura': 'Rustning',
