  'Balsa a dois': 'Flåte for to',
  'Barraca de tiro': 'Skytebod',
  'Bata nas lagartas que saírem das tocas. No coelhinho, não!': 'Slå larvene som kommer opp av hulene. Ikke den lille kaninen!',
  'Bata quando aparecer a flor igual à do quadrinho. Na figura errada, está fora.': 'Slå når blomsten lik den i rammen dukker opp. På feil figur er du ute.',
  'Batata': 'Potet',
  'Bate quando der a flor': 'Slå på blomsten',
