  'Bomba de semente': 'Frøbombe',
  'Bomba de semente pronta': 'Frøbombe klar',
  'Bombeie quando o anel acender. Fora do ritmo, o ar escapa.': 'Pump når ringen lyser. Ute av takt slipper lufta ut.',
  'Brasas da fogueira': 'Bålets glør',
  'Cabo de guerra': 'Tautrekking',
  'Cada um rema de um lado: a remada empurra a balsa para o outro. Juntos, ela vai para a frente. Peguem as cenouras!': 'Hver padler på sin side: et tak skyver flåten mot den andre siden. Sammen går den rett fram. Ta gulrøttene!',
  'Caiu! Agora é torcer de longe.': 'Skutt ned! Nå er det å heie på avstand.',
  'Canteiro que encolhe': 'Bed som krymper',
  'Cartas do celeiro': 'Låvekort',
