  'Chuva de cenouras': 'Gulrotregn',
  'Cinco': 'Fem',
  'Coelhos em teco-tecos sobre a horta, atirando ervilhas e uma cenoura teleguiada de cada vez. Dois acertos dá para aguentar; o terceiro derruba. O último no ar ganha.': 'Kaniner i små propellfly over grønnsakshagen, som skyter erter og én styrt gulrot om gangen. To treff tåler du; det tredje skyter deg ned. Den siste i lufta vinner.',
  'Colheita em dupla': 'Innhøsting for to',
  'Coma a torta com a sua dupla, alternando ◀ e ▶. Quem acabar primeiro ganha!': 'Spis paien med makkeren din, vekselvis ◀ og ▶. Den som blir først ferdig, vinner!',
  'Come as folhas': 'Spiser bladene',
  'Corrida de barquinhos no lago, no riacho e no mangue. A água desliza: tire o pé antes da curva, cuidado com a margem e aproveite a correnteza e as argolas. No Solo, contra o relógio e os fantasmas dos amigos.': 'Båtløp på innsjøen, i bekken og i mangroven. Vannet er glatt: slipp gassen før svingen, pass på bredden, og bruk strømmen og ringene. Solo mot klokka og vennenes spøkelser.',
  'Corrida de cavalinho': 'Kjepphestløp',
  'Dano da turma: {n}': 'Gjengens skade: {n}',
  'De galho em galho': 'Fra gren til gren',
  'De que cor é a folha da cenoura?': 'Hvilken farge har gulrotbladet?',
  'Desça pegando as cenouras. Das pedras, fuja!': 'Gå nedover og ta gulrøttene. Unngå steinene!',
  'Descubra quem está escondido. Uma chance só: quanto antes, mais vale.': 'Finn ut hvem som gjemmer seg. Bare én sjanse: jo før, jo mer verdt.',
  'Destampe os potes': 'Åpne glassene',
  'Desvie das brasas. São só três corações!': 'Unngå glørne. Bare tre hjerter!',
  'Dez': 'Ti',
  'Do que uma planta precisa para crescer?': 'Hva trenger en plante for å vokse?',
  'Dois acertos você aguenta; o terceiro derruba. Curva fechada perto da cerca protege por um instante.': 'To treff tåler du; det tredje skyter deg ned. En krapp sving nær gjerdet beskytter et øyeblikk.',
  'Duas': 'To',
  'Duelo de aviõezinhos': 'Papirflyduell',
  'Em dupla: quem está no galho solta os morangos maduros, e quem está embaixo apanha com a cesta.': 'To og to: den på grenen slipper de modne jordbærene, og den nedenfor tar dem i kurven.',
  'Em que dia é o aniversário do Syden?': 'Hvilken dag har Syden bursdag?',
  'Empurre os outros para fora do canteiro. A borda que pisca vai cair!': 'Dytt de andre ut av bedet. Kanten som blinker, faller snart!',
  'Encurrale a galinha. Cansada, ela fica lenta.': 'Driv høna opp i et hjørne. Når hun er sliten, blir hun treg.',
  'Escolha a resposta certa antes que o tempo acabe.': 'Velg riktig svar før tiden er ute.',
  'Escolher a torre': 'Velg tårn',
  'Esconda-se onde a lanterna não vai olhar. Quem tem a lanterna procura!': 'Gjem deg der lykta ikke ser. Den med lykta leter!',
  'Esconde-esconde na horta': 'Gjemsel i grønnsakshagen',
  'Espanta a chuva': 'Skremmer bort regnet',
  'Esta subida já tinha começado quando você abriu: você assiste.': 'Denne klatringen var allerede i gang da du åpnet den: du ser på.',
  'Fase {n} de {total}': 'Fase {n} av {total}',
  'Foguete de cenoura': 'Gulrotrakett',
  'Frear': 'Brems',
  'Fuga do rio': 'Flukt på elva',
  'Fuja das marcas no chão. Passe por cima de um torrão azulado para pegá-lo e atire de volta na toupeira; a bomba de semente é uma por fase.': 'Unngå merkene på bakken. Gå over en blålig jordklump for å plukke den opp, og kast den tilbake på moldvarpen; én frøbombe per fase.',
  'Gire cada tampa para o lado da seta, depressa. O lado errado aperta de novo.': 'Vri hvert lokk mot pila, fort. Feil vei strammer det igjen.',
  'Guarde a ordem da dança. No fim, diga quem dançou na lâmpada marcada.': 'Husk rekkefølgen i dansen. Til slutt sier du hvem som danset på den merkede lampen.',
  'Guarde onde fica cada pote e ponha todos de volta no lugar.': 'Husk hvor hvert glass hører hjemme, og sett alle tilbake på plass.',
  'Lá de cima rolam abóboras; quem sobe troca de faixa para fugir delas!': 'Ovenfra ruller gresskar; de som klatrer, bytter felt for å unngå dem!',
  'Lagarta': 'Larve',
  'Lago da horta': 'Grønnsakshagens dam',
  'Leite e mel': 'Melk og honning',
  'Lesma': 'Snegle',
  'Leve a nuvem até o canteiro com sede.': 'Før skyen til det tørste bedet.',
  'Leve as três tábuas até a ponte. Cuidado com as pedras que afundam!': 'Bær de tre plankene til brua. Pass på steinene som synker!',
  'Mangue': 'Mangrove',
  'Moletom': 'Hettegenser',
