  'Na cama': 'I sengen',
  'Na Corrida dos coelhos, o kart do mascote parece o quê?': 'Hva ligner maskotens gokart på i Kaninløpet?',
  'Na sua vez, vire uma carta ou guarde as cenouras. A raposa leva tudo!': 'Når det er din tur, snu et kort eller ta vare på gulrøttene. Reven tar alt!',
