  'Sem vidas: agora é torcer pela turma.': 'Ingen liv igjen: nå er det å heie på gjengen.',
  'Siga os bichos de toca em toca. No fim, aponte onde está o do balão.': 'Følg dyrene fra hule til hule. Til slutt peker du på hvor den med ballongen er.',
  'Silo': 'Silo',
  'Solte o cipó quando ele estiver na faixa clara.': 'Slipp lianen når den er i den lyse stripen.',
  'Solte quando o nabo apontar para o campo. Girando mais rápido, vai mais longe.': 'Slipp når nepa peker mot jordet. Jo fortere den snurrer, jo lenger går den.',
  'Suba até o cata-vento. O que cai e os corvos levam de volta ao último andar.': 'Klatre opp til værhanen. Fall og kråkene sender deg tilbake til siste etasje.',
  'Suba o celeiro por tábuas, fardos e vigas que se mexem até o cata-vento lá no alto, desviando das ferramentas que caem e dos corvos. No Solo, contra o relógio e os fantasmas dos amigos.': 'Klatre opp låven på planker, høyballer og bjelker som beveger seg, helt opp til værhanen på toppen, og unngå verktøy som faller og kråkene. Solo mot klokka og vennenes spøkelser.',
