  '{n} voltas': '{n} runder',
  'A energia é a vida e o turbo: bater na borda gasta, a faixa cor-de-rosa recarrega.': 'Energien er livet ditt og turboen din: å treffe kanten bruker den, den rosa stripen lader den opp.',
  'A nave explodiu: a energia acabou.': 'Skipet eksploderte: energien tok slutt.',
  'Posição: {posicao} de {total}': 'Plassering: {posicao} av {total}',
  'Escolher a pista': 'Velg banen',
  'Corrida de naves-cenoura numa pista suspensa, muito mais rápida que o kart. A energia é a vida e o turbo: bater na borda gasta, a faixa cor-de-rosa recarrega, e sair da pista é cair. No Solo, contra o relógio e os fantasmas dos amigos.': 'Et løp med gulrotskip på en svevende bane, mye raskere enn karten. Energien er livet ditt og turboen din: å treffe kanten bruker den, den rosa stripen lader den opp, og å kjøre av banen er å falle. Solo, mot klokka og vennenes spøkelser.',
  'Os karts numa arena fechada, cada um com três balões. Pegue as caixas e use os itens para estourar os balões dos outros: quem fica sem balão sai, e ganha quem sobrar.': 'Kartene i en lukket arena, hver med tre ballonger. Ta kassene og bruk gjenstandene til å sprekke de andres ballonger: den som ikke har flere ballonger, er ute, og den som blir igjen, vinner.',
  'Esquadrilha da toca': 'Skvadronen i hula',
  'Aviõezinhos de cenoura contra a praga da horta: desvie das sementes, pegue os reforços e derrube o espantalho mecânico no fim. A turma voa as mesmas ondas, e a esquadrilha soma os pontos.': 'Små gulrotfly mot skadedyrene i grønnsakshagen: unngå frøene, ta forsterkningene og skyt ned det mekaniske fugleskremselet til slutt. Gjengen flyr de samme bølgene, og skvadronens poeng legges sammen.',
  'O espantalho caiu!': 'Fugleskremselet er nede!',
  'A praga venceu desta vez.': 'Skadedyrene vant denne gangen.',
