  'Minigolfe 3D': 'Minigolf 3D',
  'Oito buracos em 3D, com rampas, castelo e moinho, todos jogando o mesmo ao mesmo tempo. Arraste para mirar e dar a força, e solte. Ganha quem somar menos tacadas.': 'Åtte hull i 3D, med ramper, slott og vindmølle, alle spiller det samme samtidig. Dra for å sikte og gi kraft, og slipp. Den med færrest slag totalt vinner.',
  'Ver o buraco de cima': 'Se hullet ovenfra',
  'Fora da pista! Mais uma tacada.': 'Utenfor banen! Ett slag til.',
  'Arraste para o lado para mirar e para baixo para a força, e solte. No teclado: as setas miram, e o Espaço segurado dá a força.': 'Dra til siden for å sikte og nedover for kraft, og slipp. Med tastaturet: pilene sikter, og mellomrom holdt inne gir kraften.',
  'Futebol dos coelhos': 'Kaninfotball',
  'Futebol de campo pequeno, visto de cima. Encoste na bola para conduzir, segure Espaço para chutar mais forte e passe com X. Na sala, os times se completam com robôs.': 'Fotball på liten bane, sett ovenfra. Berør ballen for å drible, hold inne mellomrom for å skyte hardere, og pass med X. I rommet fylles lagene opp med roboter.',
