  'Ninguém para jogar.': 'Ingen å spille med.',
  'Caça às pragas da horta': 'Skadedyrjakt i grønnsakshagen',
  'Corvos e gafanhotos atacam a horta. Mire e clique para acertar antes que fujam: a munição é contada, e cada onda vem mais rápida. Ganha quem fizer mais pontos.': 'Kråker og gresshopper angriper grønnsakshagen. Sikt og klikk for å treffe dem før de slipper unna: ammunisjonen er talt, og hver bølge kommer raskere. Den som får flest poeng, vinner.',
  'Mire e clique nas pragas antes que fujam. Cada tiro gasta uma cenoura.': 'Sikt og klikk på skadedyrene før de slipper unna. Hvert skudd bruker en gulrot.',
