  'Setas para correr, Espaço para pular (segure para ir mais alto).': 'Piltaster for å løpe, mellomrom for å hoppe (hold inne for å komme høyere).',
  'Nenhum amigo jogou esta fase ainda.': 'Ingen venner har spilt denne banen ennå.',
  'Chuva na horta: todo mundo ganha {n} cenouras.': 'Regn i hagen: alle får {n} gulrøtter.',
  '{nome} achou {n} cenouras escondidas.': '{nome} fant {n} gjemte gulrøtter.',
