  'Faltou gente: a partida acabou antes do fim, sem troféus.': 'For få folk: runden sluttet før tiden, uten trofeer.',
  'Saiu antes do fim': 'Gikk før slutten',
  'Jogar o dado': 'Kast terningen',
  '{nome} comprou a cenoura dourada!': '{nome} kjøpte gullgulroten!',
  'Comprar a cenoura dourada por {preco} cenouras?': 'Kjøpe gullgulroten for {preco} gulrøtter?',
  'Comprar': 'Kjøp',
  '{nome} chegou à cenoura dourada.': '{nome} kom fram til gullgulroten.',
  'Quantas rodadas?': 'Hvor mange runder?',
  'Os coelhos defendem a horta de raposas, corvos e um texugo. Andem juntos, batam em combo e cuidem uns dos outros: de 1 a 4 pessoas.': 'Kaninene forsvarer hagen mot rever, kråker og en grevling. Gå sammen, slå i kombo og pass på hverandre: 1 til 4 personer.',
  'Pulo do coelho': 'Kaninhoppet',
  'Uma corrida de plataforma: correr, pular e não cair. Sozinho, contra o relógio e os fantasmas dos amigos; com a turma, ao vivo, numa fase ou nas três.': 'Et plattformløp: løp, hopp og ikke fall. Alene mot klokka og vennenes spøkelser; med gjengen direkte, på én bane eller alle tre.',
  'Troque dois legumes vizinhos para juntar três ou mais iguais. A pilha sobe sem parar: não deixe chegar ao topo. Com a turma, as cadeias e os combos mandam caixotes para os outros.': 'Bytt to grønnsaker ved siden av hverandre for å samle tre eller flere like. Stabelen stiger uten stans: ikke la den nå toppen. Med gjengen sender kjeder og komboer kasser til de andre.',
  'Seis buracos de minigolfe, todos jogando o mesmo ao mesmo tempo. Puxe a bola para trás e solte para dar a tacada. Ganha quem somar menos tacadas.': 'Seks minigolfhull, alle spiller det samme samtidig. Dra ballen bakover og slipp for å slå. Den med færrest slag totalt vinner.',
  'Cada um joga o dado na sua vez e anda pela horta. Junte cenouras para comprar a cenoura dourada, e depois de cada rodada a turma joga um microjogo. Ganha quem tiver mais cenouras douradas.': 'Alle kaster terningen når det er deres tur og går rundt i hagen. Samle gulrøtter for å kjøpe gullgulroten, og etter hver runde spiller gjengen et minispill. Den med flest gullgulrøtter vinner.',
