  'Ande pelas capitais do Brasil, compre cidades e cobre aluguel de quem parar nelas. Com uma região inteira, dá para construir prédios. Troque, dispute nos leilões e não fique sem dinheiro.': 'Gå rundt blant Brasils hovedsteder, kjøp byer og krev leie av dem som stopper der. Med en hel region kan du bygge bygninger. Bytt, by på auksjoner og ikke gå tom for penger.',
