  'O dominó de sempre, de 2 a 4 pessoas (com 4, em duplas). Encaixe as pedras pelas pontas, e quem bater primeiro leva os pontos das mãos dos outros.': 'Klassisk domino for 2 til 4 personer (med 4 i lag på to). Legg brikkene ved endene, og den som først går ut, får poengene fra de andres hender.',
  'O truco paulista, com vira e manilha, em 2 ou em duplas de 4. Peça truco, aumente para seis, nove e doze, ou corra. Ganha quem fizer 12 pontos.': 'Truco fra São Paulo, med vendekort og trumfer, for 2 eller 4 i lag på to. Rop truco, høy til seks, ni og tolv, eller stikk av. Den som får 12 poeng, vinner.',
  'As damas brasileiras: comer é obrigatório, para a frente e para trás, e a dama anda a diagonal inteira. A sala assiste.': 'Brasiliansk dam: Det er tvang å slå, forover og bakover, og damen går hele diagonalen. Rommet ser på.',
  'Cada um esconde a sua frota e atira no mar do outro. Acertou, atira de novo. Vence quem afundar a frota inteira primeiro. A sala assiste.': 'Hver gjemmer flåten sin og skyter i den andres hav. Treff? Da skyter du igjen. Den som først senker hele flåten, vinner. Rommet ser på.',
