  'Cozinha da toca': 'Hulens kjøkken',
  'Pegue os ingredientes nos caixotes, pique na tábua, cozinhe no fogão e no forno sem queimar, monte no prato e entregue na janela. Todos recebem os mesmos pedidos: ganha quem entregar mais pratos em 3 minutos.': 'Ta ingrediensene fra kassene, hakk dem på fjølen, stek og bak dem på komfyren og i ovnen uten å brenne dem, legg dem på tallerkenen og lever i luken. Alle får de samme bestillingene: den som leverer flest tallerkener på 3 minutter, vinner.',
