  "Registros limitados de Docker, SSH, logind e kernel dos três boots mais recentes. Podem conter endereços IP.": "Begrensede logger fra Docker, SSH, logind og kjernen fra de tre siste oppstartene. Kan inneholde IP-adresser.",
