  'Para quando a escolha automática errar: a resolução e os quadros ficam os que você escolher, do começo ao fim da transmissão.': "For når det automatiske valget tar feil: oppløsningen og bildene blir de du velger, fra start til slutt i sendingen.",
  // O Syden Broadcast (16/11/2026)
  'Os efeitos de voz e de câmera feitos no seu computador, sem enviar nada a um servidor.': "Stemme- og kameraeffektene som lages på datamaskinen din, uten å sende noe til en server.",
  // A Masmorra da Toca (16/11/2026)
  'Masmorra da Toca': "Hulens fangehull",
  'Atravessem juntos a toca do rei-cogumelo: salas cheias de bichos, um baú com a cenoura que vai e volta, botões que pedem dois ao mesmo tempo e a porta trancada. De 1 a 4 pessoas.': "Kom dere gjennom soppkongens hule sammen: rom fulle av dyr, en kiste med gulroten som flyr ut og tilbake, knapper som trenger to samtidig, og den låste døra. 1 til 4 personer.",
  // O Ringue da Toca (16/11/2026)
  'Ringue da Toca': "Hulens ring",
  'Boxe de reflexo contra três adversários do computador. Leia o aviso de cada golpe, esquive ou defenda e bata na brecha. Bater quando a luva brilha enche a estrela do soco forte.': "Refleksboksing mot tre datamotstandere. Les varselet for hvert slag, unngå eller blokker, og slå i åpningen. Slår du når hansken glimter, fylles stjernen til det harde slaget.",
  'Esquivar': "Unngå",
  'Abaixar e defender': "Duk og blokker",
  'Socar': "Slå",
  'Soco forte': "Hardt slag",
  'Aperte os socos para levantar!': "Trykk på slagene for å reise deg!",
  'Lutas vencidas: {n}': "Vunne kamper: {n}",
  'Nocaute!': "Knockout!",
  // O Comando Cenoura (16/11/2026)
  'Comando Cenoura': "Gulrotkommandoen",
  'Correr e atirar com a turma: o lança-cenouras mira em oito direções, a granada abre caminho e quem solta os coelhinhos presos ganha reforço. O dragão espera no fim: de 1 a 4 pessoas.': "Løp og skyt med gjengen: gulrotkasteren sikter i åtte retninger, granaten åpner veien, og den som befrir kaninungene i burene, får forsterkning. Dragen venter til slutt: 1 til 4 personer.",
  'Andar e mirar': "Gå og sikt",
  'Granada': "Granat",
  // A Rota Estelar (16/11/2026)
  'Rota Estelar': "Stjerneruten",
  'Coelhos em naves pela superfície de um planeta e pelo espaço: atire, segure o tiro para travar a mira, gire para desviar dos tiros e escolha o caminho na bifurcação. A turma voa a mesma rota, e o chefe espera no fim.': "Kaniner i romskip over overflaten på en planet og ut i rommet: skyt, hold skuddet inne for å låse målet, snurr for å avverge skudd og velg vei ved veiskillet. Gjengen flyr samme rute, og sjefen venter på slutten.",
  'Pirueta': "Snurr",
  'Segure para travar a mira': "Hold inne for å låse",
  // O Pinball da Horta (16/11/2026)
  'Pinball da Horta': "Kjøkkenhage-pinball",
  'Uma mesa de pinball na horta: segure a mola, rebata nos repolhos e derrube as três cenouras para acender a toca do coelho, que solta mais uma bola. Três bolas, e sacudir demais trava a mesa.': "Et pinballbord i kjøkkenhagen: hold fjæren, sprett mot kålhodene og velt de tre gulrøttene for å tenne kaninhullet, som slipper ut én ball til. Tre baller, og for mye risting låser bordet.",
