  'Nenhuma conversa ainda. Toque em alguém na lista de pessoas da comunidade e escolha "Enviar mensagem".': "Ingen samtaler ennå. Trykk på noen i medlemslisten i fellesskapet og velg «Send melding».",
  "Varia": "Varierer",
  "Vitória de {nomes}": "Seier til {nomes}",
  "Vocês derrubaram os dois centros da vila da outra equipe.": "Dere rev ned begge bysentrumene til det andre laget.",
  // Os mini-games e as insígnias (19/11/2026)
  "A cidade que ninguém compra vai a leilão. Hipotecar uma cidade dá dinheiro, mas ela não cobra aluguel.": "En by som ingen kjøper, går på auksjon. Å pantsette en by gir penger, men da krever den ikke inn leie.",
  "A dica acende a peça que move. O problema com dica não pontua; na corrida, ela tira 10 segundos.": "Hintet lyser opp brikken som skal flyttes. En oppgave med hint gir ikke poeng; i løpet koster det 10 sekunder.",
  "A manilha é o valor seguinte ao da vira e ganha de todas. Entre elas: ouros, espadas, copas e paus, o zap.": "Trumfen er verdien etter vendekortets og slår alle. Seg imellom: ruter, spar, hjerter og kløver, zap.",
  "A última nave de cada volta sai.": "Det siste skipet i hver runde ryker ut.",
  "Abaixar": "Dukk",
  "Acertos em sequência: {n}": "Riktige på rad: {n}",
  "Ande pelo dado e compre a capital onde parar. Quem para na cidade de outro paga aluguel.": "Gå etter terningen og kjøp hovedstaden der du lander. Den som lander på en annens by, betaler leie.",
  "Cada linha, coluna e bloco de 3 × 3 tem os números de 1 a 9, sem repetir.": "Hver rad, kolonne og 3 × 3-blokk har tallene 1 til 9 uten gjentakelser.",
  "Cada um recebe 3 cartas. Leva a mão quem ganhar 2 das 3 rodadas.": "Alle får 3 kort. Den som vinner 2 av de 3 rundene, tar hånden.",
  "Campeonato": "Mesterskap",
  "Com 11 pontos, a dupla vê as cartas e decide se joga a mão de onze. Vence quem chegar a 12.": "Med 11 poeng ser laget kortene og bestemmer om det spiller ellevehånden. Den som når 12, vinner.",
  "Com a região inteira, construa até 4 prédios: o aluguel sobe a cada um.": "Med hele regionen bygger du opptil 4 bygninger: leien stiger for hver.",
  "Com estrelas, o soco forte (★) gasta todas de uma vez e dói mais.": "Med stjerner bruker det harde slaget (★) alle på én gang og gjør mer vondt.",
  "Dica": "Hint",
  "Dica: este problema não pontua": "Hint: denne oppgaven gir ikke poeng",
  "Dica: tira 10 segundos": "Hint: koster 10 sekunder",
  "Eliminação": "Utslagning",
  "Encoste uma pedra numa ponta da mesa com o mesmo número.": "Legg en brikke med samme tall mot en ende på bordet.",
  "Escolha a casa e depois o número. O lápis anota só para você.": "Velg ruten og så tallet. Blyanten noterer bare for deg.",
  "Esquive do golpe e soque logo depois: é o contra-ataque, e vale estrela.": "Unngå slaget og slå rett etter: det er motangrepet, og det gir en stjerne.",
