  "Saara": "Sahara",
  "Sai um animal secreto, e cada um chuta outros. Cada chute mostra o que bate com o secreto: a classe, a dieta, onde ele vive e o peso. Quem acertar com menos chutes ganha mais pontos.": "Et hemmelig dyr trekkes, og alle gjetter på andre. Hver gjetning viser hva som stemmer med det hemmelige: klassen, kostholdet, hvor det lever og vekten. Den som treffer med færrest gjetninger, får flest poeng.",
  "Sai um dinossauro secreto, e cada um chuta outros. Cada chute mostra o que bate com o secreto: o período, a dieta, o grupo, o comprimento e onde ele foi achado. Quem acertar com menos chutes ganha mais pontos.": "En hemmelig dinosaur trekkes, og alle gjetter på andre. Hver gjetning viser hva som stemmer med den hemmelige: perioden, kostholdet, gruppen, lengden og hvor den ble funnet. Den som treffer med færrest gjetninger, får flest poeng.",
  "Sai um elemento químico secreto, e cada um chuta outros. Cada chute mostra o que bate com o secreto: a família, o estado físico, o período, o grupo e o número atômico. Quem acertar com menos chutes ganha mais pontos.": "Et hemmelig grunnstoff trekkes, og alle gjetter på andre. Hver gjetning viser hva som stemmer med det hemmelige: familien, aggregattilstanden, perioden, gruppen og atomnummeret. Den som treffer med færrest gjetninger, får flest poeng.",
  "Sai um estado secreto do Brasil, e cada um chuta outros. Cada chute mostra a distância e a direção até o secreto, a região, a população, a área, o litoral e a fronteira com outro país. Quem acertar com menos chutes ganha mais pontos.": "En hemmelig brasiliansk delstat trekkes, og alle gjetter på andre. Hver gjetning viser avstanden og retningen til den hemmelige, regionen, folketallet, arealet, kysten og grensen mot et annet land. Den som treffer med færrest gjetninger, får flest poeng.",
