  "Banir": "Utesteng",
  "{pessoa} sai da comunidade e das chamadas dela na hora, e só volta se alguém que administra desbanir.": "{pessoa} forlater fellesskapet og samtalene der med en gang, og kommer bare tilbake hvis noen som administrerer, opphever utestengingen.",
  "Quem administra esta comunidade baniu a sua conta, e por isso não dá para entrar.": "De som administrerer dette fellesskapet, har utestengt kontoen din, og derfor kan du ikke komme inn.",
  "Só quem administra a comunidade pode banir alguém.": "Bare de som administrerer fellesskapet, kan utestenge noen.",
  "Só quem administra a comunidade pode desbanir alguém.": "Bare de som administrerer fellesskapet, kan oppheve en utestenging.",
  "Essa pessoa não está banida.": "Denne personen er ikke utestengt.",
  "Só quem administra a comunidade fixa mensagens.": "Bare de som administrerer fellesskapet, fester meldinger.",
  "Só as mensagens do canal podem ser fixadas, não as de um tópico.": "Bare meldinger i kanalen kan festes, ikke de i en tråd.",
  "Este canal já tem 50 mensagens fixadas. Desafixe uma antes.": "Denne kanalen har allerede 50 festede meldinger. Løsne én først.",
  "(editada)": "(redigert)",
  "Editar mensagem": "Rediger melding",
  "Canal de avisos: só quem administra escreve aqui. Para conversar sobre um aviso, abra um tópico nele.": "Kunngjøringskanal: bare administratorer skriver her. Vil du snakke om en kunngjøring, åpner du en tråd i den.",
  "Canais de avisos": "Kunngjøringskanaler",
